import re, sys
lines = open(sys.argv[1]).read().split('\n')
W = max(len(l) for l in lines)
G = [l.ljust(W) for l in lines]
H = len(G)
VERT = set('|│/\\')
HOR = set('-~+')

def ch(r, c):
    if 0 <= r < H and 0 <= c < W: return G[r][c]
    return ' '

def find(name):
    parts = name.split()
    res = []
    for r, l in enumerate(G):
        for m in re.finditer(re.escape(parts[-1]), l):
            res.append((r, m.start()))
    return res

def box_of(r, c):
    # find box bottom border: scan down from r for row where many horizontal chars around c
    # box columns: scan left on row r for side char
    left = c
    while left > 0 and ch(r, left) not in '|│': left -= 1
    # bottom row
    rb = r
    while True:
        rb += 1
        seg = G[rb][c-2:c+6]
        if sum(x in '-~+' for x in seg) >= 4: break
    rt = r
    while True:
        rt -= 1
        seg = G[rt][c-2:c+6]
        if sum(x in '-~+' for x in seg) >= 4: break
    # extent of bottom border
    a = c; b = c
    while ch(rb, a-1) in '-~+ ' and (ch(rb, a-1) != ' ' or ch(rb, a-2) in '-~+'): a -= 1
    while ch(rb, b+1) in '-~+ ' and (ch(rb, b+1) != ' ' or ch(rb, b+2) in '-~+'): b += 1
    return rt, rb, a, b

def name_in_box(rt, rb, a, b):
    out = []
    for r in range(rt+1, rb):
        s = G[r][a:b+1].strip(' |│+')
        s = s.strip()
        if s: out.append(s)
    return ' '.join(out)

def follow_down(r, c):
    """r,c is a vertical char; follow down. return ('bar', r, c) or ('box', r, c) or None"""
    while True:
        nr = r + 1
        if nr >= H: return None
        # check for horizontal at nr near c
        for dc in (0, -1, 1, -2, 2):
            x = ch(nr, c+dc)
            if x in VERT or (x == '_' ):
                pass
        cand = None
        for dc in (0, -1, 1, -2, 2):
            x = ch(nr, c+dc)
            if x in VERT:
                cand = c+dc; break
        if cand is not None:
            r, c = nr, cand; continue
        # horizontal?
        for dc in (0, -1, 1, -2, 2):
            if ch(nr, c+dc) in HOR:
                return ('hor', nr, c+dc)
        return None

def bar_extent(r, c, maxgap=3):
    a = c
    while True:
        k = 1
        while k <= maxgap and ch(r, a-k) == ' ': k += 1
        if k <= maxgap and ch(r, a-k) in HOR: a -= k
        else: break
    b = c
    while True:
        k = 1
        while k <= maxgap and ch(r, b+k) == ' ': k += 1
        if k <= maxgap and ch(r, b+k) in HOR: b += k
        else: break
    return a, b

def is_box_top(r, c):
    # row r+1 contains letters near c, or row r+2
    for rr in (r+1, r+2):
        seg = G[rr][c-12:c+12]
        if re.search(r'[A-Za-zÀ-ž]{2}', seg): return True
    return False

def box_from_top(r, c):
    # find name below
    for rr in range(r+1, r+5):
        m = None
        seg = G[rr]
        # locate a word near c
        for mm in re.finditer(r'[^\s|│+\-~]+', seg):
            if abs((mm.start()+mm.end())/2 - c) < 14 and re.search('[A-Za-zÀ-ž]', mm.group()):
                return box_of(rr, mm.start())
    return None

def children(person_box):
    rt, rb, a, b = person_box
    # vertical from bottom
    res = []
    starts = [cc for cc in range(a, b+1) if ch(rb+1, cc) in VERT]
    for s in starts:
        f = follow_down(rb+1, s)
        if not f: continue
        _, hr, hc = f
        if is_box_top(hr, hc) and not any(ch(hr+1, x) in '|' for x in []):
            bx = box_from_top(hr, hc)
            # determine if it's a bar instead: check verticals below the line
        # treat as bar: find descending verticals
        ba, bb = bar_extent(hr, hc)
        desc = [cc for cc in range(ba, bb+1) if ch(hr+1, cc) in VERT]
        if not desc and is_box_top(hr, hc):
            res.append(box_from_top(hr, hc)); continue
        for d in desc:
            g = follow_down(hr+1, d)
            if not g: continue
            _, kr, kc = g
            bx = box_from_top(kr, kc)
            if bx: res.append(bx)
    return res

def person(name):
    for r, c in find(name):
        first = name.split()[0]
        bx = box_of(r, c)
        nm = name_in_box(*bx)
        if first in nm: return bx
    raise Exception(name)

if __name__ == '__main__':
    root = person(sys.argv[2])
    def show(bx, depth, maxd):
        print('  '*depth + name_in_box(*bx), bx)
        if depth < maxd:
            for k in children(bx):
                show(k, depth+1, maxd)
    show(root, 0, int(sys.argv[3]))
